PRIMARY-REPLICA REPLICATION - read queries route to replicas,
writes go to the primary:

const dbRouter = {
  getReadDb: () => readReplica, // SELECT -> replica
  getWriteDb: () => primaryDb  // INSERT/UPDATE/DELETE -> primary
};

// THE REPLICATION-LAG CONSISTENCY CONCERN (Module 29 lesson 3's
// exact EVENTUAL CONSISTENCY model, now applied to database replication):
// A write on the primary takes genuine, measurable time (often
// milliseconds) to PROPAGATE to the replica(s). A read during
// this window returns STALE data.

// DELIBERATE CONSISTENCY ROUTING - Module 29 lesson 3's evidence-
// based choice applied to specific query types:
async function getUserById(userId: string, requireStrong: boolean) {
  if (requireStrong) {
    // genuinely CRITICAL reads (immediately after a write that
    // matters) -> primary, strong consistency
    return primaryDb.query('SELECT * FROM users WHERE id = $1', [userId]);
  }
  // non-critical reads (dashboard, social feed) -> replica,
  // eventual consistency, accepting the replication-lag trade-off
  return readReplica.query('SELECT * FROM users WHERE id = $1', [userId]);
}

