// SHARDING KEY SELECTION - every row must be unambiguously routable
// to one and only one shard, based on one specific key
function getShardForUser(userId: string, totalShards: number): number {
  // consistent hash (Module 29 lesson 4's exact technique) ensures
  // minimal data movement when adding shards
  return consistentHash(userId) % totalShards;
}

// SIMPLE, SINGLE-SHARD QUERY - unchanged from Module 19:
async function getUserOrders(userId: string) {
  const shardId = getShardForUser(userId, 4);
  return shards[shardId].query(
    'SELECT * FROM orders WHERE user_id = $1', [userId]
  ); // all of userId's orders are on ONE shard - still simple
}

// THE GENUINE TRADE-OFF: CROSS-SHARD QUERY - becomes complex
async function getTopOrdersByRevenue() {
  // PROBLEM: no single shard holds ALL orders - each shard holds
  // a distinct, non-overlapping subset by user_id
  const results = await Promise.all(
    shards.map(shard => shard.query(
      'SELECT * FROM orders ORDER BY amount DESC LIMIT 10'
    ))
  );
  // Must manually merge and re-sort results from ALL shards
  return results.flat().sort((a, b) => b.amount - a.amount).slice(0, 10);
  // THIS is the genuine, unavoidable complexity cost of sharding -
  // why lesson 1's bottleneck evidence is genuinely essential first

