codingChallenge.solutionExample:
class DatabaseRouter {
  constructor(
    private primaryDb: DatabaseClient,
    private readReplica: DatabaseClient
  ) {}

  async query(sql: string, params: unknown[], requireStrongConsistency = false) {
    const db = requireStrongConsistency ? this.primaryDb : this.readReplica;
    return db.query(sql, params);
  }

  async write(sql: string, params: unknown[]) {
    return this.primaryDb.query(sql, params);
  }

  async readAfterWrite(sql: string, params: unknown[]) {
    // explicitly routes to primary to guarantee seeing the most
    // recent write, avoiding the replication-lag stale-read risk
    return this.primaryDb.query(sql, params);
  }
}

