The complete ETL pattern, directly applying Module 28's discipline:

// EXTRACT - cursor-based, incremental
async function extractNewOrders(lastProcessedId: string | null) {
  const query = lastProcessedId
    ? { _id: { $gt: lastProcessedId } }
    : {}; // first run: process everything
  return db.orders.find(query).sort({ _id: 1 }).limit(1000).toArray();
}

// TRANSFORM - reshape production data to analytics shape
function transformOrder(order: Order): AnalyticsRecord {
  return {
    order_id: order._id.toString(),
    user_id: order.userId.toString(),
    total_amount: order.items.reduce((s, i) => s + i.price * i.qty, 0),
    item_count: order.items.length,
    created_date: order.createdAt.toISOString().split('T')[0]
  };
}

// LOAD - idempotent upsert (Module 28 lesson 3 applied to data):
// re-running with same order_id updates, never creates a duplicate
async function loadRecord(record: AnalyticsRecord) {
  await analyticsDb.query(
    `INSERT INTO order_analytics
       (order_id, user_id, total_amount, item_count, created_date)
     VALUES ($1, $2, $3, $4, $5)
     ON CONFLICT (order_id) DO UPDATE SET
       total_amount = EXCLUDED.total_amount,
       item_count = EXCLUDED.item_count`,
    [record.order_id, record.user_id,
     record.total_amount, record.item_count, record.created_date]
  );
}

