async function runOrderAnalyticsPipeline() {
  const state = await pipelineStateDb.findOne({ name: 'order-analytics' })
    ?? { lastProcessedId: null };

  let processed = 0;
  let cursor = state.lastProcessedId;

  while (true) {
    const batch = await extractNewOrders(cursor);
    if (batch.length === 0) break; // genuinely caught up

    for (const order of batch) {
      await loadRecord(transformOrder(order)); // idempotent
      cursor = order._id.toString(); // advance cursor
    }

    // Persist cursor after each batch - if pipeline fails BETWEEN
    // batches, next restart begins from this checkpoint, not
    // from the very beginning
    await pipelineStateDb.updateOne(
      { name: 'order-analytics' },
      { $set: { lastProcessedId: cursor, lastRunAt: new Date() } },
      { upsert: true }
    );

    processed += batch.length;
    console.log(`Processed ${processed} total, cursor: ${cursor}`);
  }
}

