async function extractNewEvents(lastProcessedId: string | null) {
  const query = lastProcessedId ? { _id: { $gt: lastProcessedId } } : {};
  return db.user_events.find(query).sort({ _id: 1 }).limit(500).toArray();
}

function transformEvent(event: UserEvent): AnalyticsRecord {
  return {
    event_id: event._id.toString(),
    user_id: event.userId.toString(),
    event_type: event.eventType,
    created_date: event.createdAt.toISOString().split('T')[0]
  };
}

async function loadRecord(record: AnalyticsRecord) {
  await analyticsDb.query(
    `INSERT INTO event_analytics (event_id, user_id, event_type, created_date)
     VALUES ($1, $2, $3, $4)
     ON CONFLICT (event_id) DO UPDATE SET event_type = EXCLUDED.event_type`,
    [record.event_id, record.user_id, record.event_type, record.created_date]
  );
}

async function runEventAnalyticsPipeline() {
  const state = await pipelineStateDb.findOne({ name: 'event-analytics' })
    ?? { lastProcessedId: null };
  let cursor = state.lastProcessedId;
  while (true) {
    const batch = await extractNewEvents(cursor);
    if (batch.length === 0) break;
    for (const event of batch) {
      await loadRecord(transformEvent(event));
      cursor = event._id.toString();
    }
    await pipelineStateDb.updateOne(
      { name: 'event-analytics' },
      { $set: { lastProcessedId: cursor } },
      { upsert: true }
    );
  }
}

